userscript.function:


var indexObj = $var.module = new SepoaSSO({
    cont:mainFrame,
    mode:Sepoa.request.login || "login",
    service:"loginSSO",
    sendParams:(Sepoa.params)?Sepoa.params.param:null
});

indexObj.attachEvent("onLoginEnd", function(so){
    if(so.status == '1'){
        location.href = window.CONTEXT_NAME + "/Main.sux";
    } else {
        location.href = window.CONTEXT_NAME + "/";
    }
});

indexObj.send();
